SELECT c.relname table_name,(xpath('/row/row_count/text()',x.doc))[1]::text row_count,(xpath('/row/data_md5/text()',x.doc))[1]::text data_md5 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL (SELECT query_to_xml(format('SELECT count(*) AS row_count, md5(coalesce(string_agg(to_jsonb(t)::text, chr(10) ORDER BY to_jsonb(t)::text), '''')) AS data_md5 FROM public.%I t%s',c.relname,CASE c.relname WHEN 'business_operation_log' THEN ' WHERE NOT (uid IN (''9657a0e3-3d37-4e09-ad74-4a350367efdd''))' WHEN 'command_receipt' THEN ' WHERE NOT (uid IN (''bff67349-5ecb-4969-bcd2-4a350367efee''))' WHEN 'document_sequence' THEN ' WHERE NOT (uid IN (''1f6ca9fc-66e8-4b66-9913-4a350367efb6''))' WHEN 'packing_list_head' THEN ' WHERE NOT (uid IN (''269d6921-0c54-4e90-8582-1f00a458c628''))' WHEN 'packing_list_line' THEN ' WHERE NOT (uid IN (''269d6921-0c54-4e90-8582-1f00a458c629'',''269d6921-0c54-4e90-8582-1f00a458c62a''))' ELSE '' END),false,true,'') doc) x WHERE n.nspname='public' AND c.relkind='r' ORDER BY c.relname
